/**
 * The BIMI logo stays valid SVG Tiny PS, and matches the favicon.
 *
 * A BIMI logo is fetched and parsed by mailbox providers, not by a
 * browser, and the profile they accept is narrow: `draft-svg-tiny-ps-
 * abrotman-00`. A file that violates it is not rendered leniently, it is
 * rejected, and the sender silently keeps the letter avatar. There is no
 * error message anywhere in that loop, which is why this is pinned here
 * rather than left to be noticed.
 *
 * Both files are generated by `scripts/generate-bimi-logo.py` from the
 * real DM Serif Display outlines, so the letters cannot drift from the
 * brand face. See `docs/95`.
 *
 * @vitest-environment node
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = process.cwd();
const BIMI = readFileSync(join(ROOT, 'public/bimi-logo.svg'), 'utf8');
const FAVICON = readFileSync(join(ROOT, 'src/app/icon.svg'), 'utf8');

/** Elements the profile forbids (draft §2.3, via SVG Tiny 1.2 sections). */
const FORBIDDEN_ELEMENTS = [
  'script', // §15 scripting
  'a', // §14 linking
  'image', // §5.7 images
  'switch', // §5.8.2
  'animate',
  'animateColor',
  'animateMotion',
  'animateTransform',
  'set', // §16 animation
  'audio',
  'video', // §12 multimedia
  'foreignObject',
  'style', // not in the profile; colours must be attributes
];

describe('BIMI logo is valid SVG Tiny PS', () => {
  it('declares the profile on the root element', () => {
    // draft §2.1: the document MUST be SVG Tiny 1.2 with the tiny-ps profile.
    expect(BIMI).toMatch(/<svg[^>]*\sversion="1\.2"/);
    expect(BIMI).toMatch(/<svg[^>]*\sbaseProfile="tiny-ps"/);
    expect(BIMI).toMatch(/<svg[^>]*xmlns="http:\/\/www\.w3\.org\/2000\/svg"/);
  });

  it('has exactly one non-empty title, as a child of svg', () => {
    // draft §2.1: the title element MUST be present, MUST NOT be empty,
    // and MUST occur only once as a sub-element of svg.
    const titles = [...BIMI.matchAll(/<title>([\s\S]*?)<\/title>/g)];
    expect(titles).toHaveLength(1);
    expect(titles[0][1].trim().length).toBeGreaterThan(0);
  });

  it('contains none of the forbidden elements', () => {
    const present = FORBIDDEN_ELEMENTS.filter((el) =>
      new RegExp(`<${el}[\\s/>]`, 'i').test(BIMI),
    );
    expect(present, 'forbidden by draft-svg-tiny-ps-abrotman-00 §2.3').toEqual([]);
  });

  it('carries no x or y on the root element', () => {
    // draft §6.2 names these as what Illustrator adds and the profile
    // does not permit.
    const root = /<svg([^>]*)>/.exec(BIMI)?.[1] ?? '';
    expect(root).not.toMatch(/\sx=/);
    expect(root).not.toMatch(/\sy=/);
  });

  it('references nothing outside itself', () => {
    // §3.1 wants a self-contained document; a provider will not fetch our
    // fonts or stylesheets, so anything external simply fails to render.
    expect(BIMI).not.toMatch(/xlink:href/);
    expect(BIMI).not.toMatch(/url\(/);
    // The SVG namespace is itself an http URL, so the check is that it is
    // the ONLY one — not that no URL appears at all.
    const urls = BIMI.match(/https?:\/\/[^"'\s)]+/g) ?? [];
    expect(urls).toEqual(['http://www.w3.org/2000/svg']);
  });

  it('is square, so a circular avatar crop is centred', () => {
    const vb = /viewBox="0 0 (\d+) (\d+)"/.exec(BIMI);
    expect(vb, 'no viewBox').not.toBeNull();
    expect(vb![1]).toBe(vb![2]);
  });

  it('sets the letters as outlines, never as text', () => {
    // A mailbox provider has no access to DM Serif Display. `<text>` would
    // render in whatever the provider falls back to, or not at all.
    expect(BIMI).not.toMatch(/<text[\s>]/);
    expect(BIMI).not.toMatch(/font-family/);
    expect(BIMI).toMatch(/<path /);
  });

  it('stays small enough to be fetched without complaint', () => {
    expect(Buffer.byteLength(BIMI)).toBeLessThan(32 * 1024);
  });
});

describe('the favicon is the same mark', () => {
  it('shares its outlines with the BIMI logo', () => {
    // Both come out of one generator. If these diverge, the tab icon and
    // the email avatar have stopped being the same logo.
    const paths = (svg: string) => [...svg.matchAll(/<path d="([^"]+)"/g)].map((m) => m[1]);
    expect(paths(FAVICON)).toEqual(paths(BIMI));
    expect(paths(BIMI).length).toBe(3); // L, D, and the accent dot
  });

  it('uses the brand colours', () => {
    expect(BIMI).toContain('#0F766E'); // EMAIL_COLORS.primary
    expect(BIMI).toContain('#D97706'); // EMAIL_COLORS.accent
    expect(BIMI).toContain('#FFFFFF');
  });

  it('no longer sets the letters in a font the brand does not use', () => {
    // It was Georgia `<text>`, which is absent on most Linux and Android
    // devices, so the tab icon fell back to an arbitrary serif.
    expect(FAVICON).not.toMatch(/Georgia/i);
    expect(FAVICON).not.toMatch(/<text[\s>]/);
  });
});
